document.addEventListener("DOMContentLoaded", async function () {
  const video = document.getElementById("registration-video");
  const canvas = document.getElementById("registration-canvas");
  const photo = document.getElementById("registration-photo");
  const capture = document.getElementById("registration-capture");
  const status = document.getElementById("registration-status");
  const resetBtn = document.getElementById("registration-reset");

  const DESCRIPTORS_TO_COLLECT = 12;
  const FRAME_DELAY = 120;

  let collectedDescriptors = [];
  let capturedImage = null;
  let isConfirmMode = false;

  // =============================
  // LOAD MODELS
  // =============================
  const modelUrl = "/assets/mapl_customization/models";
  await Promise.all([
    faceapi.nets.tinyFaceDetector.loadFromUri(modelUrl),
    faceapi.nets.faceLandmark68Net.loadFromUri(modelUrl),
    faceapi.nets.faceRecognitionNet.loadFromUri(modelUrl),
  ]);

  // =============================
  // CAMERA
  // =============================
  const stream = await navigator.mediaDevices.getUserMedia({
    video: { facingMode: "user" },
  });
  video.srcObject = stream;
  await new Promise((r) => (video.onloadedmetadata = r));

  capture.disabled = false;
  status.innerText = "Keep your face steady and click Capture";

  resetBtn.onclick = () => location.reload();

  // =============================
  // CAPTURE BUTTON
  // =============================
  capture.addEventListener("click", async () => {
    if (!isConfirmMode) {
      await collectDescriptors();
      return;
    }

    // =============================
    // CONFIRM & SAVE
    // =============================
    const employee = prompt("Enter Employee ID:");
    const registration_code = prompt("Enter Registration Code:");

    if (!employee || !registration_code) {
      status.innerText = "Registration cancelled.";
      return;
    }

    status.innerText = "Saving face data...";

    frappe.call({
      method:
        "mapl_customization.customizations_for_mapl.employee_gps_attendance.update_face_descriptor",
      args: {
        employee: employee,
        registration_code: registration_code,
        descriptors: collectedDescriptors, // 🔥 MULTIPLE
        image_data: capturedImage,
      },
      callback: () => {
        status.innerText = "Face registered successfully!";
        capture.disabled = true;
        video.srcObject.getTracks().forEach(t => t.stop());
      },
      error: () => {
        status.innerText = "Error saving face data";
      },
    });
  });

  // =============================
  // MULTI-DESCRIPTOR COLLECTION
  // =============================
  async function collectDescriptors() {
    collectedDescriptors = [];
    status.innerText = "Capturing face samples...";

    const ctx = canvas.getContext("2d");
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;

    // Capture reference image
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    capturedImage = canvas.toDataURL("image/png");
    photo.src = capturedImage;

    for (let i = 0; i < DESCRIPTORS_TO_COLLECT; i++) {
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

      const detection = await faceapi
        .detectSingleFace(
          canvas,
          new faceapi.TinyFaceDetectorOptions({
            inputSize: 320,
            scoreThreshold: 0.6,
          })
        )
        .withFaceLandmarks()
        .withFaceDescriptor();

      if (detection) {
        collectedDescriptors.push(Array.from(detection.descriptor));
        status.innerText = `Captured ${collectedDescriptors.length}/${DESCRIPTORS_TO_COLLECT}`;
      }

      await new Promise((r) => setTimeout(r, FRAME_DELAY));
    }

    if (collectedDescriptors.length < 6) {
      status.innerText = "Face unstable. Try again.";
      collectedDescriptors = [];
      return;
    }

    // Preview
    video.style.display = "none";
    photo.style.display = "block";
    capture.innerText = "Confirm & Register";
    isConfirmMode = true;
    status.innerText = "Confirm photo and register";
  }
});

/**
 * ===============================================================
 * DAILY GPS + FACE ATTENDANCE
 * ---------------------------------------------------------------
 * Captures employee face + GPS location and posts attendance
 * to ERPNext. Uses face-api.js for recognition and browser
 * geolocation with accuracy stabilization.
 *
 * Flow:
 * 1. Load registered employee face descriptors from ERPNext
 * 2. Load face-api models
 * 3. Start camera
 * 4. Capture photo → GPS → face detection → face matching
 * 5. Overlay metadata on image
 * 6. Compress image and post attendance
 * ===============================================================
 */
document.addEventListener("DOMContentLoaded", async () => {

  /* ===================== DOM REFERENCES ===================== */
  const video=document.getElementById("attendance-video"),
        canvas=document.getElementById("attendance-canvas"),
        photo=document.getElementById("attendance-photo"),
        status=document.getElementById("attendance-status"),
        capture=document.getElementById("attendance-capture"),
        post=document.getElementById("attendance-post");

  capture.disabled=true; post.disabled=true;
  status.innerText="Loading employee descriptors...";
  window.labeledDescriptors=[];

  /* ================= LOAD FACE DESCRIPTORS ================= */
  /* Fetches registered employee face descriptors from ERPNext.
     Handles backward compatibility:
     - Old format: [128]
     - New format: [[128], [128], ...] */
    await frappe.call({
      method: "mapl_customization.customizations_for_mapl.employee_gps_attendance.get_employee_descriptors",
      async: false,
      callback: async function (r) {
        if (!r.message) return;
    
        window.labeledDescriptors = await Promise.all(
          r.message.map(async e => {
            // Decompress OR fallback to old formats
            let raw = e.descriptor_compressed
              ? await decompressDescriptor(e.descriptor_compressed)
              : (typeof e.descriptor === "string"
                  ? JSON.parse(e.descriptor)
                  : e.descriptor);

            // Backward compatibility: single [128] → [[128]]
            if (raw.length === 128) raw = [raw];
    
            const descriptors = raw.map(d =>
              new Float32Array(d.map(x => parseFloat(x)))
            );
    
            return new faceapi.LabeledFaceDescriptors(
              `${e.employee_id}|${e.employee_name}`,
              descriptors
            );
          })
        );
      }
    });


  if(!validateLabeledDescriptors(window.labeledDescriptors)){
    status.innerText="Error: invalid face descriptors."; return;
  }

  /* ================= LOAD FACE-API MODELS ================= */
  status.innerText="Loading face models...";
  const modelUrl="/assets/mapl_customization/models";
  await Promise.all([
    faceapi.nets.tinyFaceDetector.loadFromUri(modelUrl),
    faceapi.nets.faceLandmark68Net.loadFromUri(modelUrl),
    faceapi.nets.faceRecognitionNet.loadFromUri(modelUrl)
  ]);

  /* FaceMatcher threshold: lower = stricter matching */
  const faceMatcher=new faceapi.FaceMatcher(window.labeledDescriptors,0.40);

  /* ===================== CAMERA SETUP ===================== */
  status.innerText="Starting camera...";
  try{
    const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:"user"}});
    video.srcObject=stream;
    await new Promise(r=>video.onloadedmetadata=r);
  }catch(err){
    status.innerText="Camera not permitted: "+err.message; return;
  }
  status.innerText="Ready. Click 'Capture Photo'.";
  capture.disabled=false;

  /* ===================== CAPTURE FLOW ===================== */
  capture.addEventListener("click",async()=>{
    capture.disabled=true;

    /* Capture current frame after camera stabilization */
    const ctx=canvas.getContext("2d");
    canvas.width=video.videoWidth; canvas.height=video.videoHeight;
    status.innerText="Hold still…";
    await new Promise(r=>setTimeout(r,300)); await waitForStableFrame();
    ctx.drawImage(video,0,0,canvas.width,canvas.height);
    stopCamera(video);

    photo.src=canvas.toDataURL("image/png");
    photo.style.display="block"; video.style.display="none";

    /* -------------------- GPS CAPTURE -------------------- */
    /* Attempts multiple GPS reads and returns best accuracy */
    if(!navigator.geolocation){
      status.innerText="GPS not supported";
      await restartCamera(video,canvas,photo,capture); return;
    }
    let pos;
    try{
      status.innerText="Getting precise location…";
      pos=await getGeoFenceLocation({desiredAccuracy:25,maxWaitTime:8000});
    }catch(err){
      status.innerText="GPS error: "+err.message;
      await restartCamera(video,canvas,photo,capture); return;
    }
    const {latitude,longitude}=pos.coords;

    /* ---------------- FACE DETECTION ---------------- */
    status.innerText="Detecting face…";
    let detection;
    try{
      detection=await faceapi.detectSingleFace(
        canvas,new faceapi.TinyFaceDetectorOptions({inputSize:320,scoreThreshold:0.4})
      ).withFaceLandmarks().withFaceDescriptor();
      if(!detection) throw new Error("Face not detected");
    }catch(err){
      status.innerText=err.message;
      await restartCamera(video,canvas,photo,capture); return;
    }
    if(!validateDetectionDescriptor(detection.descriptor)){
      status.innerText="Invalid face data."; return;
    }

    /* ---------------- FACE MATCHING ---------------- */
    status.innerText="Matching face…";
    let bestMatch;
    try{ bestMatch=faceMatcher.findBestMatch(detection.descriptor); }
    catch{
      status.innerText="FaceMatcher failed."; capture.disabled=false; return;
    }
    if(bestMatch.label==="unknown"){
      status.innerText="Face not recognized. Distance:"+bestMatch.distance.toFixed(3);
      await restartCamera(video,canvas,photo,capture); return;
    }

    /* ---------------- SUCCESS ---------------- */
    /* Overlay attendance metadata and prepare payload */
    const [employeeId,employeeName]=bestMatch.label.split("|");
    drawAttendanceOverlay(canvas,{
      name:employeeName,employeeId,latitude,longitude,timestamp:new Date()
    });
    photo.src=canvas.toDataURL("image/png");

    post.latestAttendance={
      employee:employeeId,
      name:employeeName,
      image_data:await compressToTargetSize(canvas,5),
      attendance_latitude:latitude,
      attendance_longitude:longitude
    };

    status.innerText="Face recognized: "+employeeName;
    post.disabled=false;
  });

  /* ================= POST ATTENDANCE ================= */
  post.addEventListener("click",()=>{
    if(!post.latestAttendance){
      status.innerText="No attendance to post."; return;
    }
    status.innerText="Posting attendance...";
    frappe.call({
      method:"mapl_customization.customizations_for_mapl.employee_gps_attendance.post_attendance",
      args:{
        employee:post.latestAttendance.employee,
        latitude:post.latestAttendance.attendance_latitude,
        longitude:post.latestAttendance.attendance_longitude,
        image_data:post.latestAttendance.image_data
      },
      callback(){ status.innerText="Successfully Marked!"; },
      error(err){ status.innerText="Error: "+err.message; }
    });
  });
});

/* ===============================================================
 * HELPER FUNCTIONS
 * =============================================================== */

/** Validates ERPNext face descriptors */
function validateLabeledDescriptors(list){
  return Array.isArray(list)&&list.every(ld=>
    typeof ld.label==="string" &&
    Array.isArray(ld.descriptors) &&
    ld.descriptors.every(d=>d instanceof Float32Array && d.length===128 && !Array.from(d).some(isNaN))
  );
}

/** Validates a detected face descriptor */
function validateDetectionDescriptor(d){
  return d instanceof Float32Array && d.length===128 && !Array.from(d).some(isNaN);
}

/** Stops all active camera tracks */
function stopCamera(video){
  video.srcObject?.getTracks().forEach(t=>t.stop()); video.srcObject=null;
}

/** Restarts camera after error or retry */
async function restartCamera(video,canvas,photo,capture){
  stopCamera(video);
  canvas.getContext("2d").clearRect(0,0,canvas.width,canvas.height);
  photo.style.display="none";
  const stream=await navigator.mediaDevices.getUserMedia({
    video:{facingMode:"user",width:1280,height:720}
  });
  video.srcObject=stream; video.style.display="block";
  video.onloadedmetadata=()=>{ video.play(); capture.disabled=false; };
}

/** Waits for two animation frames to stabilize video */
function waitForStableFrame(){
  return new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
}

/** Compresses canvas image to target size (KB) */
async function compressToTargetSize(sourceCanvas,targetKB=5,maxWidth=320,format="image/webp"){
  const ratio=sourceCanvas.height/sourceCanvas.width;
  const width=Math.min(sourceCanvas.width,maxWidth);
  const height=Math.round(width*ratio);
  const canvas=document.createElement("canvas");
  canvas.width=width; canvas.height=height;
  canvas.getContext("2d").drawImage(sourceCanvas,0,0,width,height);
  let quality=0.9,dataUrl;
  do{
    dataUrl=canvas.toDataURL(format,quality);
    quality-=0.05;
  }while((dataUrl.length*3)/4/1024>targetKB && quality>0.1);
  return dataUrl;
}

/** Draws name, employee ID, timestamp, and GPS on image */
function drawAttendanceOverlay(canvas,{name,employeeId,latitude,longitude,timestamp}){
  const ctx=canvas.getContext("2d"),pad=12,lh=18;
  const lines=[
    `Name: ${name}`,`Employee ID: ${employeeId}`,
    `Date: ${timestamp.toLocaleDateString()}`,
    `Time: ${timestamp.toLocaleTimeString()}`,
    `Lat: ${latitude.toFixed(6)}`,`Lng: ${longitude.toFixed(6)}`
  ];
  const boxH=lines.length*lh+pad*2;
  ctx.fillStyle="rgba(0,0,0,0.6)";
  ctx.fillRect(0,canvas.height-boxH,canvas.width,boxH);
  ctx.fillStyle="#fff"; ctx.font="14px Arial";
  lines.forEach((l,i)=>ctx.fillText(l,pad,canvas.height-boxH+pad+i*lh));
}

/** Attempts multiple GPS reads and returns best accuracy */
async function getGeoFenceLocation({desiredAccuracy=30,maxWaitTime=8000,maxAttempts=3}={}){
  const start=Date.now(); let best=null;
  for(let i=0;i<maxAttempts;i++){
    if(Date.now()-start>maxWaitTime) break;
    try{
      const pos=await new Promise((res,rej)=>
        navigator.geolocation.getCurrentPosition(
          res,rej,{enableHighAccuracy:true,timeout:4000,maximumAge:0}
        )
      );
      if(!best||pos.coords.accuracy<best.coords.accuracy) best=pos;
      if(pos.coords.accuracy<=desiredAccuracy) return pos;
    }catch{}
    await new Promise(r=>setTimeout(r,600));
  }
  if(best) return best;
  throw new Error("Unable to get accurate location");
}

/**
 * Decompresses base64 + gzip JSON descriptor
 * Returns original JS object (array or array of arrays)
 */
async function decompressDescriptor(base64Data){
  const binary = Uint8Array.from(atob(base64Data), c => c.charCodeAt(0));
  const stream = new DecompressionStream("gzip");
  const decompressed = new Response(
    new Blob([binary]).stream().pipeThrough(stream)
  );
  const text = await decompressed.text();
  return JSON.parse(text);
}
